// Deterministic discrete-event model. Time in ms.
// Capacity: CONC servers, each request takes SERVICE ms of work => 40 req/s.
// The burst offers 100 req/s (GAP=10), i.e. ~2.5x capacity: deep overload.
// A request is GOODPUT only if completed <= arrival + DEADLINE.
const CONC = 4;        // bounded concurrency / number of servers
const SERVICE = 100;   // ms of work per request
const DEADLINE = 1000; // client deadline in ms
const N = 120;         // burst of 120 requests...
const GAP = 10;        // ...arriving every 10ms => 100 req/s offered vs 40 req/s capacity
const PRELOAD = 2000;  // queue already 2s deep from prior sustained overload
const arrivals = Array.from({length: N}, (_, i) => i * GAP);

// Policy A: bounded concurrency + load shedding.
// Route to the earliest-free server only if it can START immediately
// (no queueing); otherwise shed with an immediate 429 (costs ~0).
function shed() {
  const freeAt = new Array(CONC).fill(0);
  let good = 0, sheddedCount = 0;
  for (const a of arrivals) {
    let s = 0;
    for (let i = 1; i < CONC; i++) if (freeAt[i] < freeAt[s]) s = i;
    if (freeAt[s] <= a) {        // a server can start now
      const done = a + SERVICE;  // no queue wait
      freeAt[s] = done;
      if (done <= a + DEADLINE) good++;
    } else {
      sheddedCount++;            // immediate 429, no resources held
    }
  }
  return { good, sheddedCount };
}

// Policy B: unbounded FIFO queue, same servers, never sheds.
// Servers start busy (PRELOAD) to model the backlog that already
// built up before this window — congestion collapse in progress.
function unbounded() {
  const freeAt = new Array(CONC).fill(PRELOAD);
  let good = 0, timedOut = 0;
  for (const a of arrivals) {
    let s = 0;
    for (let i = 1; i < CONC; i++) if (freeAt[i] < freeAt[s]) s = i;
    const start = Math.max(a, freeAt[s]); // wait in queue if busy
    const done = start + SERVICE;
    freeAt[s] = done;
    if (done <= a + DEADLINE) good++; else timedOut++;
  }
  return { good, timedOut };
}

const A = shed();
const B = unbounded();
console.log('shed goodput=' + A.good + ' shed429=' + A.sheddedCount);
console.log('queue goodput=' + B.good + ' timedout=' + B.timedOut);
console.log(A.good > B.good ? 'PROTECT GOODPUT' : 'WORSE');
